/// <summary>
/// Class used to clean up in the Document Queue
/// </summary>
class TFMDocumentQueueCleanup extends RunBaseBatch
{
    DialogField   fieldChoice;
    QueryRun      queryRun;
    int           historyLimit;
    DialogField   dialogHistoryLimit;

    #define.CurrentVersion(2)
    #localmacro.CurrentList
        historyLimit
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase dlg                = super();

    dialogHistoryLimit = dlg.addField(extendedTypeStr(Days), "@SYS69354", "@TFM:TFM71");
    dialogHistoryLimit.value(historyLimit);
    return dlg;
}

/// <summary>
/// Indicate whether or not the class can run in new session or not.
/// </summary>
/// <returns>True if the class can run in new session. Otherwise false.</returns>
protected boolean canRunInNewSession()
{
    return true;
}

public boolean getFromDialog()
{
    historyLimit = dialogHistoryLimit.value();
    return super();
}

public static TFMDocumentQueueCleanup Construct()
{
    return new TFMDocumentQueueCleanup();
}

protected void new()
{
    super();
    queryRun = new QueryRun(querystr(TFMDocumentQueue));
}

public void run()
{
    #OCCRetryCount
    try
    {
        if (DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - dateNull() <= historyLimit)
        {
            return;
        }


        ttsbegin;
        this.progressInit("@SYS57265", 0, #AviFileDelR);

        this.doCleanup(historyLimit);

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

public void doCleanup(int _historyLimit)
{
    TFMDocumentQueue        mobDocumentQueue;
    TFMXMLTable				xmlTable;

    delete_from mobDocumentQueue where mobDocumentQueue.CreatedDateTime < DateTimeUtil::addDays(DateTimeUtil::getSystemDateTime(), - _historyLimit);

    delete_from xmlTable
            where xmlTable.RefTableId == mobDocumentQueue.TableId
        notexists join mobDocumentQueue
            where mobDocumentQueue.RecId == xmlTable.RefRecId;

}

public boolean unpack(container _packedClass)
{
    Integer         version        = RunBase::getVersion(_packedClass);
    container       packedQuery;

    switch (version)
    {
        case 1:
            [version,packedQuery] = _packedClass;
            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            this.initParmDefault();
            break;

        case #CurrentVersion:
            [version,packedQuery, #currentList] = _packedClass;
            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;

        default:
            return false;
    }
    return true;
}

public static void main(Args _args)
{
    TFMDocumentQueueCleanup mobDocumentQueueCleanup;
    mobDocumentQueueCleanup = new TFMDocumentQueueCleanup();

    if (mobDocumentQueueCleanup.prompt())
    {
        mobDocumentQueueCleanup.runOperation();
    }
}
